func testHabilitacaoToManyAddOpEntEntidades(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Habilitacao
	var b, c, d, e Entidade

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, habilitacaoDBTypes, false, strmangle.SetComplement(habilitacaoPrimaryKeyColumns, habilitacaoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Entidade{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, entidadeDBTypes, false, strmangle.SetComplement(entidadePrimaryKeyColumns, entidadeColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*Entidade{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddEntEntidades(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if first.R.HabCodigoHabilitacaos[0] != &a {
			t.Error("relationship was not added properly to the slice")
		}
		if second.R.HabCodigoHabilitacaos[0] != &a {
			t.Error("relationship was not added properly to the slice")
		}

		if a.R.EntEntidades[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.EntEntidades[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.EntEntidades().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

